    for i in range(0, n, block_size):
        for j in range(i, min(n, i + block_size)):
            if A[j][j] != 0:
                for k in range(j + 1, min(n, j + block_size)):
                    factor = -A[k][j] / A[j][j]
                    for l in range(j, min(n, j + block_size)):
                        A[k][l] += factor * A[j][l]
                rank += 1
    return rank

